-- Cuesies add-on: 5 themed tables (laundromat, bakery, campsite, science lab, bowling alley), one level per scene.
-- Run in the Supabase SQL editor. The date is a placeholder: change it before running. Each day needs five rows (level_order 1-5).
-- Same JSON as the last five entries of NEW_LEVELS in index.html.

on conflict (level_date, level_order) do update set data = excluded.data;
